function invert(obj) {
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    out[v] = k;
  }
  return out;
}

level-project.solution:
function summarise(orders) {
  const customers = [];
  let total = 0;
  for (const o of orders) {
    total += o.amount ?? 0;
    const name = o.customer?.name;
    if (name !== undefined && !customers.includes(name)) {
      customers.push(name);
    }
  }
  return { count: orders.length, total, customers };
}

